"""Box stand v7 parts regenerated by topology (noxopt), 19 Oct 2026 23:25 (Spark: run them all in topology, don't worry
about the weight, make them stronger than the geometric shapes). One part per run / chat:
    python3 stand_v7_topo.py <part> [h] [gen_cm3]
parts: bracket_e bracket_jA bracket_jB post_seg bar_half toe kb frame_endR frame_endL
Each part = drawn interfaces (bolt pads, cheeks, plates, slots: the v7 geometry's must-have features, nothing else) +
an envelope wider / taller than the v7 part + cuts (holes, nut pockets, keep-outs: the ring, the sheets, the funnel
collar, the arm sweep) + the v7 FE load cases on regions. Mass target = generated volume, set high (about 1.5 to 2x the
v7 part's generated volume) so the result is stiffer and stronger than the hand-drawn shape, not lighter.
Pipeline: arm_topo.run_part (layout -> prune thin -> connectivity -> polished build -> function / thin / wrinkle /
as-built strength -> STL in W coords: out/box_<part>_v8_W.stl + <part>_result.json). Then stand_v7_parts.print_pose
for the print STL. Needs beside it: noxopt.py, printopt.py, arm_topo.py, arm_cad.py, arm_layout.py, stand_v6_parts.py,
stand_v7_parts.py, pymoto + pypardiso + mkl (PYPARDISO_MKL_RT). W coords (box-arm.md). All C unless noted."""
import sys, os, math
import numpy as np, manifold3d as mf
import arm_layout as L
from arm_cad import box, cylY, cylX, cylZ, hull, _plane_box, _plane_cyl_t
import stand_v6_parts as S
import stand_v7_parts as V
from stand_v6_parts import FLOOR, KTOP, H
from arm_topo import PartProblem, run_part, log

X_IN, Y_FRONT, Y_BACK = V.X_IN, V.Y_FRONT, V.Y_BACK
BIG = 1e3
def jbox(a, *args): return V.jbox(a, *args)
def halfspace_x(x0):            # X > x0
    return box(x0, BIG, -BIG, BIG, -BIG, BIG)

def collar_keepout_W():
    """funnel collar v4 outer surface + the drone column below it (box-stand check rule), as one convex body in W."""
    pts = []
    for z, hw in ((95.0, 88.4), (143.6, 88.4), (237.0, 181.8), (262.0, 206.8)):
        for sx in (-1, 1):
            for sy in (-1, 1): pts.append([sx * hw, 177.0 + sy * hw, z])
    return hull(pts)

# ======================================================================= brackets (W)
def bracket_e_setup(h):
    a = 45.0; CH = 5.0; zc = 183.6 * math.sin(math.radians(a)) - 2.0
    # 20 Oct run 3: drawn = the two bolt pads only (10.2 x 20 x 5 on the station blocks' outer faces, M5 walls >= 2.35);
    # the 36-long drawn cheeks of runs 1-2 were themselves the limiting member and kept the optimizer out of that region
    # 20 Oct 14:30 run 4 (neck check): drawn = the v7c cheeks (t -18..-0.8, full block face, + 10-long bolt boss outside,
    # r 5 counterbore); run 3's 10.2-wide pads sat inside an r 5.5 access cut and hung on 2..3 mm necks
    cheeks = V.be_cheek(a, 126.0, 131.0) + V.be_cheek(a, 223.0, 228.0)
    flange = box(X_IN - 4.0, X_IN, 126.0 - V.BE_YB, 228.0 + V.BE_YB, zc - 16.0, zc + 16.0)
    drawn = cheeks + flange
    holes = None
    for y0_, y1_ in ((119.0, 140.0), (214.0, 235.0)):
        c = cylY(0, 0, y0_, y1_, 2.75).translate([V.EB_T, 0, 170.0]).transform(V.jframe(a)); holes = c if holes is None else holes + c
    for y in (150.0, 204.0): holes += cylX(y, zc, X_IN - 6, X_IN + 1, 1.7)
    ring = cylY(0, 0, 126.0, 228.0, 179.3, 180) - cheeks
    frame_side = jbox(a, -0.8, 60.0, 126.0, 228.0, 140.0, 200.0)                # beyond the end plane: the end frame's pads / webs
    access = V.be_counterbore(a, 126.0, 131.0) + V.be_counterbore(a, 223.0, 228.0)   # M5 head + hex key along Y
    for y in (150.0, 204.0): access += cylX(y, zc, X_IN - 26, X_IN - 4, 4.0)
    arm_sweep = cylY(0, 0, 97.0, 222.0, 153.5, 180)                              # heads + packs (box-arm keep-out)
    sheet = halfspace_x(X_IN)
    cuts = holes + ring + frame_side + access + arm_sweep + sheet + collar_keepout_W()
    env = box(100.0, X_IN, 108.0, 246.0, 92.0, 166.0)
    pp = PartProblem("bracket_e", h, drawn, cuts, env, build="-x", overhang=False)
    pp.support("default", box(X_IN - 1.0, X_IN + 0.5, 120.0, 234.0, zc - 20, zc + 20))
    R = dict(cheeks=cheeks)
    pp.load("drop 2 x 64 N + 13 N side", cheeks, (13, 0, -128))
    pp.load("rim pull 20 N outward (+Z -X)", cheeks, (-20, 0, 20))
    pp.load("ring push +Y 30 N", cheeks, (0, 30, 0)); pp.load("ring push -Y 30 N", cheeks, (0, -30, 0))
    pp.load("ring push -X 30 N", cheeks, (-30, 0, 0)); pp.load("ring push +X 30 N", cheeks, (30, 0, 0))
    return pp, drawn, cuts, env, 40.0

BJ_BR, BJ_AR, BJ_BL = 8.5, 5.5, 8.0      # 20 Oct 17:15 (v8, Spark): boss round each lug bolt outside each cheek: r 8.5, access r 5.5 (3.0 wall), 8 long (head 5 + 3, DEFAULT)
BJ_CHEEK = ((136.0, 149.7), (204.3, 218.0))   # cheeks widened so the boss sits fully on them (Y 136..149.7 / 204.3..218, rho 163..183.6); 149.7 / 204.3 = 0.3 off the frames' rib webs (Y 150..156 / 198..204)
BJ_RHO0 = 163.0
BJ_RING_R = 180.2                              # ring keep-out: frames reach r 179.85 (X-brace node corners, C) + 0.3 clearance + rounding
def bj_boss(a, y, t0, t1, ylim):
    """U-boss (W) round the lug bolt at Y y, rho 172, along t from t0 to t1: r 8.5 tube, its side toward the frame rib
    (beyond ylim, 0.3 off the rib) cut flat, so it is a 3.0-walled U open toward the rib (the full tube hits the rib: 95..215 mm3, C)."""
    tube = V.jcyl_t(a, t0, t1, y, 172.0, BJ_BR)
    keep = jbox(a, t0 - 1, t1 + 1, y - 20, ylim, 140.0, 200.0) if ylim > y else jbox(a, t0 - 1, t1 + 1, ylim, y + 20, 140.0, 200.0)
    return tube ^ keep
def bj_access(a, y, t0, t1, ylim):
    """access inside the boss: an obround, the hull of the r 5.5 bore and the same bore moved past ylim (11 tall, rho
    166.5..177.5, no acute tips). One convex body: a box slot tangent to the bore left a 4-face edge at the boss end (v8 rerun, C)."""
    s = 1.0 if ylim > y else -1.0
    y2 = ylim + s * (BJ_AR + 2.0)
    return mf.Manifold.batch_hull([V.jcyl_t(a, t0, t1, y, 172.0, BJ_AR), V.jcyl_t(a, t0, t1, y2, 172.0, BJ_AR)])

def bracket_j_setup(h, a):
    TP, TM = L.LUG_T; CH = 3.7; ARMS = BJ_CHEEK; zc = 172.0 * math.sin(math.radians(a))
    cheeks = None
    for ya, yb in ARMS:
        c = jbox(a, -TM - 0.3 - CH, -TM - 0.3, ya, yb, BJ_RHO0, 183.6) + jbox(a, TP + 0.3, TP + 0.3 + CH, ya, yb, BJ_RHO0, 183.6)
        cheeks = c if cheeks is None else cheeks + c
    tP0, tM1 = TP + 0.3 + CH, -TM - 0.3 - CH                                    # cheek outer faces (head side +t, nut side -t)
    bosses = None
    for y, (ya, yb) in zip(L.LUG_Y, ARMS):
        ylim = yb if yb - y < y - ya else ya                                     # the rib side of this lug
        b = bj_boss(a, y, tP0 - 0.01, tP0 + BJ_BL, ylim) + bj_boss(a, y, tM1 - BJ_BL, tM1 + 0.01, ylim)
        bosses = b if bosses is None else bosses + b
    flange = box(X_IN - 4.0, X_IN, 137.0, 217.0, zc - 16.0, zc + 16.0)
    cheeks_only = cheeks
    cheeks = cheeks + bosses                                                     # drawn cheek = plate + its boss (README Rules, Solid parts)
    drawn = cheeks + flange
    holes = None
    for y in L.LUG_Y:
        c = V.jcyl_t(a, -TM - CH - 2, TP + CH + 2, y, 172.0, L.M5_CLR_R); holes = c if holes is None else holes + c
    for y in (160.0, 194.0): holes += cylX(y, zc, X_IN - 6, X_IN + 1, 1.7)
    ring = cylY(0, 0, 120.0, 235.0, BJ_RING_R, 180) - cheeks                     # 20 Oct v8: r 179.3 let jA v8 run 1 sit 0.6 into the frames' X-brace nodes (r 179.85, C)
    lugs = jbox(a, -TM - 0.3, TP + 0.3, 120.0, 235.0, 150.0, 185.0)              # the two frames' lug pair between the cheeks
    access = None
    for y, (ya, yb) in zip(L.LUG_Y, ARMS):                                       # M5 head / nut + key, inside the boss, never wider than it
        ylim = yb if yb - y < y - ya else ya
        c = bj_access(a, y, tP0, TP + 30, ylim) + bj_access(a, y, -TM - 30, tM1, ylim)
        access = c if access is None else access + c
    for y in (160.0, 194.0): access += cylX(y, zc, X_IN - 26, X_IN - 4, 4.0)
    cuts = holes + ring + lugs + access + halfspace_x(X_IN)
    env = box(150.0, X_IN, 135.0, 219.0, zc - 20.0, zc + 20.0)
    pp = PartProblem(f"bracket_j{'A' if a < 0 else 'B'}", h, drawn, cuts, env, build="-x", overhang=False)
    pp.support("default", box(X_IN - 1.0, X_IN + 0.5, 130.0, 224.0, zc - 22, zc + 22))
    for v, nm in (((30, 0, -30), "down + side"), ((0, 30, 30), "up + fore"), ((0, -30, 30), "up + aft"), ((-30, 0, 0), "-X"), ((30, 0, 0), "+X"), ((0, 0, -30), "-Z")):
        pp.load(f"ring {nm} 30 N", cheeks_only, v)                             # the lug pair loads the cheek plates
    return pp, drawn, cuts, env, 12.0

# ======================================================================= post segment (W, right-front corner, Z 0..147)
def post_seg_setup(h):
    cx, cy, SLOT, SEG = X_IN, Y_FRONT, V.SLOT, V.SEG
    wA = box(cx - 3.0, cx, cy - 15.0, cy + SLOT + 3.0, 0, SEG) + box(cx + SLOT, cx + SLOT + 3.0, cy - 15.0, cy + SLOT + 3.0, 0, SEG)
    wB = box(cx - 15.0, cx + SLOT + 3.0, cy - 3.0, cy, 0, SEG) + box(cx - 15.0, cx + SLOT + 3.0, cy + SLOT, cy + SLOT + 3.0, 0, SEG)
    drawn = wA + wB                                                              # the slot walls, 3.0 each
    slots = box(cx, cx + SLOT, cy - 16.0, cy - 3.0, -1, SEG + 1) + box(cx - 16.0, cx - 3.0, cy, cy + SLOT, -1, SEG + 1)
    holes = cylX(cy - 8.0, SEG / 2, cx - 20, cx + 10, 1.7) + cylY(cx - 8.0, SEG / 2, cy - 20, cy + 10, 1.7)
    sheets = box(cx, cx + SLOT, cy - 60, cy - 3.0, -1, SEG + 1) + box(cx - 60, cx - 3.0, cy, cy + SLOT, -1, SEG + 1)   # the sheets run on
    access = cylX(cy - 8.0, SEG / 2, cx - 30, cx - 3.0, 4.0) + cylY(cx - 8.0, SEG / 2, cy - 30, cy - 3.0, 4.0)   # M3 nut + driver
    cuts = slots + holes + sheets + access
    env = box(cx - 22.0, cx + SLOT + 10.0, cy - 22.0, cy + SLOT + 10.0, 0, SEG)
    drawn -= cuts
    pp = PartProblem("post_seg", h, drawn, cuts, env, build="-x", overhang=False)
    pp.support("default", box(cx - 25, cx + 15, cy - 25, cy + 15, -0.5, 1.0))     # standing on the floor
    top = box(cx - 25, cx + 15, cy - 25, cy + 15, SEG - 1.0, SEG + 0.5)
    for v, nm in (((-13, 0, 0), "-X"), ((13, 0, 0), "+X"), ((0, -13, 0), "-Y"), ((0, 13, 0), "+Y")):
        pp.load(f"13 N at the top {nm}", top, v)
    pp.load("side sheet pulls the outer wall +X 20 N", box(cx + SLOT, cx + SLOT + 3.0, cy - 15, cy - 3, 0, SEG), (20, 0, 0))
    pp.load("front sheet pulls the outer wall +Y 20 N", box(cx - 15, cx - 3, cy + SLOT, cy + SLOT + 3.0, 0, SEG), (0, 20, 0))
    return pp, drawn, cuts, env, 20.0

# ======================================================================= cross bar half (W)
def bar_half_setup(h):
    y0, ym, y1 = S.LAP_Y
    lap = box(-20, 20.5, y0, ym, FLOOR, KTOP)
    # 20 Oct v8 (Spark 17:07): the r 5.5 access cut reached Z -180.5, above the pad top (-181), so it could cut the pad off
    # from behind. Now: access r 5.0 (as bracket_e v7c's counterbore; M5 head 8.5), a drawn boss tube r 8.5 round it
    # (wall 3.5 above, 3.0 to the bar faces Y 46 / 62, clipped to the bar slab), and the pad grown to the boss top
    # (Z -177.5) so the head seat and the boss foot sit fully on the pad.
    # Retry (17:50): run 1 landed two 6-thick rails on the boss's back top; its 3.5 wall was their only link to the pad
    # (split off at the 2.0 erosion, 2 x 93 mm3 M). Boss gets a flat roof 6.0 over the cut (Z -175) and the pad grows to
    # match, so anything landing on the boss reaches the pad through >= 4 mm.
    BR, AR, BX0, ZR = 8.5, 5.0, 165.0, -175.0
    pad = box(177.0, X_IN, y0, y1, FLOOR, ZR)
    boss = ((cylX(54.0, -186.0, BX0, 177.0, BR) + box(BX0, 177.0, y0, y1, -186.0, ZR)) ^ box(BX0, 177.0, y0, y1, FLOOR, 0.0)) \
        - cylX(54.0, -186.0, BX0 - 1, 177.0, AR)
    feet = box(20.5, 30.0, y0, y1, FLOOR, FLOOR + 4.0) + box(165.0, 177.0, y0, y1, FLOOR, FLOOR + 4.0)
    drawn = lap + pad + boss + feet
    cuts = S.joint_holes(y0 - 1, y1 + 1) + cylX(54.0, -186.0, 170.0, 200.0, 2.75) + box(30.0, 165.0, y0 - 1, y1 + 1, FLOOR - 1, FLOOR + 1.0)
    cuts += cylX(54.0, -186.0, 140.0, 177.0, AR)                                 # M5 head + hex key along -X, inside the boss
    env = box(-20, 20.5, y0, ym, FLOOR, KTOP) + box(20.5, X_IN, y0, y1, FLOOR, -165.0)   # taller than v7 (36 vs 20)
    pp = PartProblem("bar_half", h, drawn, cuts, env, build="+y", overhang=False)
    pp.support("default", lap)
    pp.load("box on one tip 50 N up", pad, (0, 0, 50)); pp.load("tip 50 N down", pad, (0, 0, -50))
    for v, nm in (((13, 0, 0), "+X"), ((-13, 0, 0), "-X"), ((0, 13, 0), "+Y"), ((0, -13, 0), "-Y")):
        pp.load(f"sheet on the tip pad 13 N {nm}", pad, v)
    return pp, drawn, cuts, env, 45.0

# ======================================================================= toe (W)
def toe_setup(h):
    up = box(-20, 20, 197.0, 201.0, FLOOR, KTOP)
    plate = box(-36, 36, 331.0, Y_FRONT, FLOOR, KTOP)
    boss = None
    for s in (1, -1):
        b = box(min(s * 18, s * 34), max(s * 18, s * 34), 325.0, 331.0, FLOOR, -183.0); boss = b if boss is None else boss + b
    drawn = up + plate + boss
    cuts = None
    for s in (1, -1):
        c = cylY(s * 26, -191.0, 320.0, Y_FRONT + 1, 2.75) + V.hexY(s * 26, -191.0, 324.0, 329.0) + cylY(s * 10, -191.0, 196.0, 202.0, 2.75)
        cuts = c if cuts is None else cuts + c
    cuts += box(-40, 40, 190.0, 197.0, FLOOR - 1, -140) + box(-40, 40, Y_FRONT, 350.0, FLOOR - 1, -140)   # cradle and sheet
    for s in (1, -1):
        cuts += cylY(s * 10, -191.0, 201.0, 240.0, 5.5) + cylY(s * 26, -191.0, 290.0, 325.0, 5.5)   # head + key; nut in from -Y
    env = box(-36, 36, 197.0, Y_FRONT, FLOOR, -171.0)
    pp = PartProblem("toe", h, drawn, cuts, env, build="+z", overhang=False)
    pp.support("default", up)
    for v, nm in (((0, -13, 0), "push -Y"), ((0, 13, 0), "pull +Y"), ((0, 0, 13), "lift"), ((0, 0, -13), "down"), ((13, 0, 0), "+X"), ((-13, 0, 0), "-X")):
        pp.load(f"front sheet on the plate 13 N {nm}", plate, v)
    pp.load("misuse 50 N on the plate -Y", plate, (0, -50, 0))
    return pp, drawn, cuts, env, 40.0

# ======================================================================= KB (W)
PSU = (25.0, 89.0, -50.0, -10.0)        # PSU on the floor beside the mast: X, Y ranges (box-stand.md, DEFAULT); zip ties round a generated member
def kb_setup(h):
    s = S.SPIG; y0, y1 = Y_BACK, S.KB_Y[1]
    spig = box(-s["x"], s["x"], s["y0"], s["y1"], FLOOR, s["ztop"]) - box(-s["x"] + s["wall"], s["x"] - s["wall"], s["y0"] + s["wall"], s["y1"] - s["wall"], FLOOR + 3.0, s["ztop"] + 1)
    floor = box(-20, 20, y0 + 6.0, y1, FLOOR, FLOOR + 3.0)
    end = box(-20, 20, y1, y1 + S.PLATE_T, FLOOR, KTOP)
    rear = box(-36, 36, y0, y0 + 6.0, FLOOR, KTOP)
    boss = None
    for sx in (1, -1):
        b = box(min(sx * 18, sx * 34), max(sx * 18, sx * 34), y0 + 6.0, y0 + 12.0, FLOOR, -183.0); boss = b if boss is None else boss + b
    # 20 Oct v8 (README Rules, Solid parts: access cut never wider than its pad, boss wall >= 3 round it). Audit of the
    # 14:45 setup: rear nut access r 5.5 in a 16 x 18 boss left 2.5; the 4 base-joint head cuts r 5.0 reached the plate top
    # (0 above the upper pair), sat 0.08 apart and notched the floor to 2.3. Fix: boss shells 3.0 round both, drawn.
    above_floor = box(-BIG, BIG, -BIG, BIG, FLOOR, BIG)
    rtube = None
    for sx in (1, -1):                                                              # rear nut + driver: shell r 8.5 behind the boss,
        t = cylY(sx * 26, -191.0, y0 + 12.0, PSU[2] - 0.5, 8.5)                     # stops at the PSU keep-out (Y -50.5)
        rtube = t if rtube is None else rtube + t
    hc = [cylY(x, z, 0.0, y1, 5.0) for x, z in S.JOINT_BOLTS]
    head_pocket = (hc[0] + hc[1] + hc[2] + hc[3]).hull() ^ box(-BIG, BIG, -BIG, BIG, FLOOR + 3.0, BIG)   # one pocket, floor stays 3.0
    hs = [cylY(x, z, y1 - 12.0, y1 + S.PLATE_T, 8.0) for x, z in S.JOINT_BOLTS]
    head_shell = (hs[0] + hs[1] + hs[2] + hs[3]).hull() ^ above_floor              # 3.0 round the pocket, Y 28..46 (closes the plate over the upper holes)
    drawn = spig + floor + end + rear + boss + (rtube ^ above_floor) + head_shell
    cuts = S.joint_holes(y1 - 1, y1 + S.PLATE_T + 1)
    for sx in (1, -1):
        cuts += cylY(sx * 26, -191.0, y0 - 1, y0 + 20, 2.75) + V.hexY(sx * 26, -191.0, y0 + 8.0, y0 + 13.0)
    for y, z in S.XBOLTS: cuts += cylX(y, z, -40, 40, 2.75, 48)
    for sx in (1, -1): cuts += cylY(sx * 26, -191.0, y0 + 12.0, y0 + 40.0, 5.5)    # nut + driver in from +Y
    cuts += head_pocket                                                             # base-joint heads + key inside the U
    cuts += box(PSU[0] - 0.5, PSU[1], PSU[2] - 0.5, PSU[3] + 0.5, FLOOR - 1, -129.0)   # PSU beside the mast (box-stand.md, DEFAULT)
    cuts += box(-s["x"] + s["wall"], s["x"] - s["wall"], s["y0"] + s["wall"], s["y1"] - s["wall"], FLOOR + 3.0, s["ztop"] + 5)   # spigot bore stays open
    cuts += box(-22, 22, -62, 2, -130.0, 50.0) - box(-18, 18, -58, -2, -131.0, 51.0)   # the mast sleeve wall (the spigot inside it is drawn)
    cuts += box(-40, 40, y1 + S.PLATE_T, 80, FLOOR - 1, 0) + box(-40, 40, y0 - 10, y0, FLOOR - 1, 0)   # bar laps / sheet
    env = box(-36, 36, y0, y1 + S.PLATE_T, FLOOR, -130.0) + spig        # the spigot is in the grid (loads at its top), generated material stops at Z -130
    pp = PartProblem("kb", h, drawn, cuts, env, build="+z", overhang=False)
    pp.support("default", box(-40, 40, y0 - 1, y1 + 10, FLOOR - 0.5, FLOOR + max(1.0, 1.25 * h)))   # 20 Oct v8: the bottom cell layer (was FLOOR + 1.0: 0 elements at h 2.0)
    top = box(-s["x"] - 1, s["x"] + 1, s["y0"] - 1, s["y1"] + 1, -72.0, s["ztop"] + 1)
    yp = top ^ box(-40, 40, -30.0, 10, -80, -40); ym = top ^ box(-40, 40, -70, -30.0, -80, -40)
    xp = top ^ box(0, 40, -70, 10, -80, -40); xm = top ^ box(-40, 0, -70, 10, -80, -40)
    Mx = (19.6 * 0.060 + 20 * 0.175 + 20 * 0.052) * 1000
    pp.load("arm lean: +Y half of the spigot top down", yp, (0, 10, -Mx / 28 / 2 - 9.8)); pp.load("arm lean: -Y half up", ym, (0, 10, Mx / 28 / 2 - 9.8))
    pp.load("yaw: +X half +Y", xp, (0, 3500 / 18 / 2, 0)); pp.load("yaw: -X half -Y", xm, (0, -3500 / 18 / 2, 0))
    pp.load("side 20 N at the bay (spigot top +X)", top, (20, 0, 0))
    pp.load("rear sheet push 13 N", rear, (0, 13, 0)); pp.load("rear sheet pull 13 N", rear, (0, -13, 0))
    return pp, drawn, cuts, env, 40.0

# ======================================================================= end frames (drawn in the module's top frame, as stand_v6_parts)
def frame_end_setup(h, kind):
    jp = kind == "endR"; side_end = -1 if jp else +1; p = 30 if jp else -210
    tp, tm_ = L.LUG_T
    drawn = None; cuts = None
    def add(a, b):
        return b if a is None else a + b
    for y in L.LUG_Y:
        if jp:
            drawn = add(drawn, _plane_box(+1, -tp, -0.05, y - 7, y + 7, *L.LUG_RHO))
            cuts = add(cuts, _plane_cyl_t(+1, -tp - 1.0, 1.0, y, 172.0, L.M5_CLR_R))
        else:
            drawn = add(drawn, _plane_box(-1, -tm_, -0.05, y - 7, y + 7, *L.LUG_RHO))
            cuts = add(cuts, _plane_cyl_t(-1, -tm_ - 1.0, 1.0, y, 172.0, L.M5_CLR_R) + S.nut_pocket_mX(y))
    for ys0, ys1 in L.DT_SEG:
        drawn += _plane_box(+1, -tp, -0.05, ys0, ys1, L.DT_RHO[0], L.DT_RHO[1]) if jp else _plane_box(-1, -8.0, -0.05, ys0, ys1, *L.DT_RHO)
    if not jp: cuts += S.groove_frame()
    fe = V.free_end_v7(side_end)                                                  # station blocks + webs + floors + pads, holes cut
    drawn += fe
    T_BACK, T_SEAT = 22.4, 37.4
    for yp_ in S.PADS_Y:
        cuts += _plane_cyl_t(side_end, T_BACK - 5, T_SEAT + 5, yp_, 176.5, 1.7)
        cuts += _plane_box(side_end, -1.0, T_BACK - 0.5, yp_ - 6, yp_ + 6, 170.0, 181.0)   # the key lane stays open
    for y0_, y1_ in ((126.0, 162.0), (192.0, 228.0)):
        c = cylY(0, 0, y0_, y1_, 2.75).translate([V.EB_T, 0, 170.0]).transform([[math.cos(H), 0, math.sin(H), 0], [0, 1, 0, 0], [-math.sin(H), 0, math.cos(H), 0]])
        cuts += c if side_end > 0 else c.mirror([1, 0, 0])
    c = cylY(0, 0, 157.0, 197.0, 5.5).translate([V.EB_T, 0, 170.0]).transform([[math.cos(H), 0, math.sin(H), 0], [0, 1, 0, 0], [-math.sin(H), 0, math.cos(H), 0]])
    cuts += c if side_end > 0 else c.mirror([1, 0, 0])                           # station-block nuts + wrench between the blocks
    jside = +1 if jp else -1; tl = tp if jp else tm_
    for y in L.LUG_Y:
        cuts += _plane_cyl_t(jside, -tl - 25.0, -tl, y, 172.0, 5.5)              # joint bolt head (endR) / nut (endL) + key, inside the frame
    gp = 0.05 if jp else 0.3; gm = 0.3 if jp else 0.05
    sec = S.sector(gp, gm, 131.0, 223.0) ^ S.annulus(145.5, 179.3, 131.0, 223.0)
    padbox = _plane_box(side_end, -0.31, 38.0, 128.0, 226.0, 160.0, 187.5)
    env = sec + padbox
    collar = collar_keepout_W().rotate([0, -(90 - p), 0])
    cuts += collar
    cuts += _plane_box(side_end, -12.0, -0.3, 120.0, 131.0, 140.0, 190.0) + _plane_box(side_end, -12.0, -0.3, 223.0, 234.0, 140.0, 190.0)   # bracket_e cheeks
    pp = PartProblem(f"frame_{kind}", h, drawn, cuts, env, build="-z", overhang=False)
    joint = _plane_box(+1 if jp else -1, -12.0, 0.5, 125.0, 229.0, 140.0, 185.0)
    blocks = _plane_box(side_end, -8.5, -0.2, 130.0, 158.0, 147.0, 180.0) + _plane_box(side_end, -8.5, -0.2, 196.0, 224.0, 147.0, 180.0)
    pp.support("default", joint); pp.support("blocks", blocks)
    pads = _plane_box(side_end, T_BACK - 0.5, T_SEAT + 0.5, 125.0, 229.0, 165.0, 188.0)
    padA = pads ^ box(-BIG, BIG, 120.0, 177.0, -BIG, BIG); padB = pads ^ box(-BIG, BIG, 177.0, 240.0, -BIG, BIG)
    # loads in the top frame: "down" in W = -Z_W; in the top frame W's -Z maps by the inverse placement. Use the frame's
    # own radial (+Z here) for the pad load direction: the pads hold the funnel against the ring's radial, the drop pushes radially inward
    pp.load("funnel + Scout 6 N + rim push 6.5 N", pads, (6.5 * side_end, 0, -6.0))
    pp.load("misuse 50 N on pad A (radial in)", padA, (0, 0, -50)); pp.load("Scout drop 64 N on pad A", padA, (0, 0, -64))
    pp.load("Scout drop 64 N on pad B", padB, (0, 0, -64))
    pp.load("rim push fore-aft 6.5 N", pads, (0, 6.5, -6))
    pp.load("drop 128 N on both pads, held by the bracket", pads, (0, 0, -128), support="blocks")
    pp.load("neighbour hangs 20 N on the joint, held by the bracket", joint, (0, 0, -20), support="blocks")
    return pp, drawn, cuts, env, 30.0

SETUP = dict(bracket_e=bracket_e_setup, bracket_jA=lambda h: bracket_j_setup(h, -15.0), bracket_jB=lambda h: bracket_j_setup(h, 15.0),
             post_seg=post_seg_setup, bar_half=bar_half_setup, toe=toe_setup, kb=kb_setup,
             frame_endR=lambda h: frame_end_setup(h, "endR"), frame_endL=lambda h: frame_end_setup(h, "endL"))
H_DEFAULT = dict(bracket_e=1.5, bracket_jA=1.5, bracket_jB=1.5, post_seg=1.5, bar_half=1.5, toe=2.0, kb=2.0, frame_endR=2.0, frame_endL=2.0)
# cloud RAM: pardiso dies at 6 GB above ~60k design cells (bracket_e at h 1.5, 137k cells, OOM 19 Oct 23:40); NOX_BACKEND=gmg
# swaps every layout (the run's and prune_thin's re-settles) for noxopt_local's multigrid solver

if __name__ == "__main__":
    part = sys.argv[1]
    h = float(sys.argv[2]) if len(sys.argv) > 2 else H_DEFAULT[part]
    if os.environ.get("NOX_BACKEND"):
        import noxopt as NO, noxopt_local as NL, functools
        _NL = NL.Layout
        def _layout(*a, masked=True, **k):                                       # noxopt_local takes no `masked` (plain-filter runs stay on noxopt)
            return _NL(*a, backend=os.environ["NOX_BACKEND"], **k)
        NO.Layout = _layout
        NO.strength_report = lambda pb, dens, thr=0.5, title="": NL.strength_report(pb, dens, thr, backend=os.environ["NOX_BACKEND"])   # 20 Oct kb v8: the as-built recheck on pardiso OOM-killed the run at 6.1 GB
    pp, drawn, cuts, env, gen = SETUP[part](h)
    env = env + drawn                      # 20 Oct 00:20: the build clips to env; a drawn body outside it would be cut off (bracket_e cheeks)
    gen = float(sys.argv[3]) if len(sys.argv) > 3 else gen
    os.makedirs("out", exist_ok=True)
    if not os.environ.get("NOX_SETUP_ONLY"):
        res, P = run_part(pp, drawn, cuts, env, gen, f"out/box_{part}_v8_W.stl")
